import random, itertools, sys
import networkx as nx
n=22
target_edges=27
max_trials=200000
for trial in range(max_trials):
    G=nx.Graph()
    G.add_nodes_from(range(n))
    # start with empty, add random edges while respecting constraints
    edges=list(itertools.combinations(range(n),2))
    random.shuffle(edges)
    for u,v in edges:
        if G.number_of_edges()>=target_edges:
            break
        G.add_edge(u,v)
        # check girth condition
        try:
            cycles=nx.cycle_basis(G)
        except Exception:
            cycles=[]
        short=False
        for c in cycles:
            if len(c)<7:
                short=True
                break
        if short:
            G.remove_edge(u,v)
            continue
        # check 3-colorable
        if nx.coloring.greedy_color(G, strategy='largest_first') is None:
            pass
        # use exact check via graph coloring? use networkx algorithm for coloring number
        # approximate: use DSATUR to get number colors
        colors=nx.coloring.greedy_color(G, strategy='DSATUR')
        if max(colors.values())+1>3:
            G.remove_edge(u,v)
            continue
    if G.number_of_edges()==target_edges:
        # final check girth
        # compute shortest cycle length
        def girth(G):
            g=10**9
            for node in G:
                # BFS
                visited={node:0}
                q=[node]
                parent={node:-1}
                while q:
                    cur=q.pop(0)
                    for nb in G[cur]:
                        if nb not in visited:
                            visited[nb]=visited[cur]+1
                            parent[nb]=cur
                            q.append(nb)
                        elif parent[cur]!=nb:
                            # found cycle
                            length=visited[cur]+visited[nb]+1
                            g=min(g,length)

            return g if g!=10**9 else None
        g=girth(G)
        if g is not None and g>=7:
